public class LimitedConcurrencyLevelTaskScheduler : TaskScheduler
{
    [ThreadStatic]
    private static bool _currentThreadIsProcessing;

    private readonly int _maxDegreeOfParallelism;
    private readonly Queue<Task> _tasks = new Queue<Task>();

    public LimitedConcurrencyLevelTaskScheduler(int maxDegreeOfParallelism)
    {
        _maxDegreeOfParallelism = maxDegreeOfParallelism;
    }

    protected override IEnumerable<Task> GetScheduledTasks()
    {
        return _tasks.ToArray();
    }

    protected override void QueueTask(Task task)
    {
        lock (_tasks)
        {
            _tasks.Enqueue(task);
        }
        ThreadPool.QueueUserWorkItem(ProcessNext);
    }

    private void ProcessNext(object _)
    {
        if (_currentThreadIsProcessing)
            return;

        _currentThreadIsProcessing = true;
        try
        {
            while (_tasks.Count > 0)
            {
                Task task;
                lock (_tasks)
                {
                    task = _tasks.Dequeue();
                }
                TryExecuteTask(task);
            }
        }
        finally
        {
            _currentThreadIsProcessing = false;
        }
    }
}

